"text-anchor\":\"middle\"};\n    if(portrait){\n      const tP = {...tA, \"text-anchor\":\"start\", \"font-size\":fs*0.8};\n      el(\"text\",{x:0.3,y:-pad*0.3,...tP},svg).textContent = attack ? \"Motståndarnas mål\" : \"Motståndarna anfaller ↓\";\n      el(\"text\",{x:0.3,y:L+pad*0.75,...tP},svg).textContent = attack ? \"Vi anfaller ↑\" : \"Vårt mål\";\n    } else {\n      el(\"text\",{x:L*0.75,y:W+pad*0.75,...tA},svg).textContent = attack ? \"Motståndarnas mål\" : \"Motståndarna anfaller ←\";\n      el(\"text\",{x:L*0.18,y:W+pad*0.75,...tA},svg).textContent = attack ? \"Vi anfaller →\" : \"Vårt mål\";\n    }\n\n    // Korridorer längs planen: yttre 14 %, inre 16 %, central 40 % av planens bredd\n    gCorr = el(\"g\",{},gRoot);\n    gCorr.style.display = opts.corr ? \"\" : \"none\";\n    {\n      const a = W*0.14, b2 = W*0.30;\n      const edges = [0, a, b2, W-b2, W-a, W];\n      const names = [[\"Yttre\",\"korridor\"],[\"Inre\",\"korridor\"],[\"Central\",\"korridor\"],[\"Inre\",\"korridor\"],[\"Yttre\",\"korridor\"]];\n      const tints = [\"rgba(255,255,255,.07)\",\"rgba(0,0,0,.06)\",\"rgba(255,255,255,.07)\",\"rgba(0,0,0,.06)\",\"rgba(255,255,255,.07)\"];\n      for(let k=0;k<5;k++){\n        el(\"rect\",{x:0,y:edges[k],width:L,height:edges[k+1]-edges[k],fill:tints[k]},gCorr);\n      }\n      [a,b2,W-b2,W-a].forEach(y=> el(\"line\",{x1:0,y1:y,x2:L,y2:y,stroke:\"rgba(255,255,255,.55)\",\"stroke-width\":M.L/320,\"stroke-dasharray\":`${M.L/90} ${M.L/120}`},gCorr));\n      const cfs = M.L/62;\n      // etiketter i båda planhalvorna, så att de syns oavsett hur planen är vänd\n      [M.L*0.62, M.L*0.38].forEach(lx=>{\n        for(let k=0;k<5;k++){\n          const cy = (edges[k]+edges[k+1])/2;\n          const tg = el(\"g\",{transform:`translate(${lx},${cy})${kitRot()}`},gCorr);\n          const t1 = el(\"text\",{y:-cfs*0.15,\"font-size\":cfs,\"font-weight\":\"700\",fill:\"rgba(255,255,255,.8)\",\"text-anchor\":\"middle\",\"paint-order\":\"stroke\",stroke:\"rgba(0,0,0,.35)\",\"stroke-width\":cfs*0.18},tg);\n          t1.textContent = names[k][0];\n          const t2 = el(\"text\",{y:cfs*0.95,\"font-size\":cfs*0.8,fill:\"rgba(255,255,255,.7)\",\"text-anchor\":\"middle\",\"paint-order\":\"stroke\",stroke:\"rgba(0,0,0,.35)\",\"stroke-width\":cfs*0.15},tg);\n          t2.textContent = names[k][1];\n        }\n      });\n    }\n\n    gOverlay = el(\"g\",{},gRoot);\n    overlayEls.box = el(\"polygon\",{fill:\"rgba(255,210,31,.13)\",stroke:\"rgba(255,225,110,.75)\",\"stroke-width\":lw,\"stroke-dasharray\":`${lw*4} ${lw*3}`},gOverlay);\n    overlayEls.l1 = el(\"polyline\",{fill:\"none\",stroke:\"rgba(255,228,120,.9)\",\"stroke-width\":lw*1.2},gOverlay);\n    overlayEls.l2 = el(\"polyline\",{fill:\"none\",stroke:\"rgba(255,228,120,.9)\",\"stroke-width\":lw*1.2},gOverlay);\n    overlayEls.l3 = el(\"polyline\",{fill:\"none\",stroke:\"rgba(255,228,120,.9)\",\"stroke-width\":lw*1.2},gOverlay);\n    overlayEls.pressArr = el(\"line\",{stroke:\"var(--press)\",\"stroke-width\":lw*2.2,\"marker-end\":\"url(#arr)\"},gOverlay);\n    overlayEls.coverArr = el(\"line\",{stroke:\"var(--cover)\",\"stroke-width\":lw*1.8,\"stroke-dasharray\":`${lw*3} ${lw*2}`},gOverlay);\n\n    gGhost = el(\"g\",{},gRoot);\n    gMark = el(\"g\",{},gRoot);\n    markEls = [];\n    for(let k=0;k<M.players.length;k++) markEls.push(el(\"line\",{stroke:\"rgba(255,255,255,.55)\",\"stroke-width\":M.L/400,\"stroke-dasharray\":`${M.L/250} ${M.L/300}`},gMark));\n    const r = M.L/52;\n    gOpp = el(\"g\",{},gRoot);\n    oppEls = M.opp.map((p,i)=>{\n      const g = el(\"g\",{style:\"cursor:grab\"},gOpp);\n      const pin = el(\"circle\",{r:r*1.6,fill:\"none\",stroke:\"transparent\",\"stroke-width\":r*0.15,\"stroke-dasharray\":`${r*0.4} ${r*0.3}`},g);\n      el(\"circle\",{r:r*1.3,fill:\"transparent\"},g); // träffyta\n      const kk = attack ? (p.gk ? KIT.usGK : KIT.us) : (p.gk ? KIT.oppGK : KIT.opp);\n      kit(g, r, kk.shirt, kk.shorts, kk.num, p.n);\n      const lab = el(\"text\",{y:r*1.85,\"font-size\":r*0.72,fill:\"rgba(255,255,255,.92)\",\"text-anchor\":\"middle\",\"font-weight\":\"700\",\"paint-order\":\"stroke\",stroke:\"rgba(0,0,0,.45)\",\"stroke-width\":r*0.12},g);\n      lab.textContent = attPos(p, attack ? ourSel[modeKey] : oppSel[modeKey]);\n      return {g, pin, lab};\n    });\n    gPlayers = el(\"g\",{},gRoot);\n    playerEls = M.players.map((p,i)=>{\n      const g = el(\"g\",{},gPlayers);\n      const ring = el(\"circle\",{r:r*1.5,fill:\"transparent\",stroke:\"transparent\",\"stroke-width\":r*0.22},g);\n      const kk = attack ? (i===0 ? KIT.oppGK : KIT.opp) : (i===0 ? KIT.usGK : KIT.us);\n      kit(g, r, kk.shirt, kk.shorts, kk.num, p.n);\n      const c = ring;\n      const lab = el(\"text\",{y:r*1.85,\"font-size\":r*0.72,fill:\"rgba(255,255,255,.92)\",\"text-anchor\":\"middle\",\"font-weight\":\"700\",\"paint-order\":\"stroke\",stroke:\"rgba(0,0,0,.45)\",\"stroke-width\":r*0.12},g);\n      lab.textContent = p.pos;\n      const pin = el(\"circle\",{r:r*1.7,fill:\"none\",stroke:\"transparent\",\"stroke-width\":r*0.15,\"stroke-dasharray\":`${r*0.4} ${r*0.3}`},g);\n      g.style.cursor = \"grab\";\n      return {g, ring, c, lab, pin};\n    });\n    ghostEls = M.players.map(()=> el(\"circle\",{r:r*0.7,fill:\"none\",stroke:\"rgba(255,255,255,.45)\",\"stroke-width\":r*0.12,\"stroke-dasharray\":`${r*0.3} ${r*0.25}`},gGhost));\n\n    gBall = el(\"g\",{style:\"cursor:grab\"},gRoot);\n    // större osynlig träffyta för touch\n    el(\"circle\",{r:M.L/22,fill:\"transparent\"},gBall);\n    ballEl = el(\"circle\",{r:M.L/85,fill:\"var(--ball)\",stroke:\"#111\",\"stroke-width\":M.L/600},gBall);\n    el(\"circle\",{r:M.L/85*2.1,fill:\"none\",stroke:\"rgba(255,255,255,.5)\",\"stroke-width\":M.L/500},gBall);\n\n    // startpositioner\n    const t = computeTargets();\n    cur = t.pts.map(p=>({...p}));\n    tgt = t.pts;\n    oppCur = oppTgt.map(p=>({...p}));\n    ballDisp = {...ball};\n    updateOverlay(t);\n    draw();\n  }\n\n  // ---------- Overlay & statistik ----------\n  let lastBase = null;\n  function updateOverlay(t){\n    lastBase = t.base;\n  }\n\n  function hull(points){\n    const pts = points.slice().sort((a,b)=>a.x===b.x? a.y-b.y : a.x-b.x);\n    const cross=(o,a,b)=>(a.x-o.x)*(b.y-o.y)-(a.y-o.y)*(b.x-o.x);\n    const lower=[];for(const p of pts){while(lower.length>=2&&cross(lower[lower.length-2],lower[lower.length-1],p)<=0)lower.pop();lower.push(p);}\n    const upper=[];for(let i=pts.length-1;i>=0;i--){const p=pts[i];while(upper.length>=2&&cross(upper[upper.length-2],upper[upper.length-1],p)<=0)upper.pop();upper.push(p);}\n    upper.pop();lower.pop();return lower.concat(upper);\n  }\n\n  function draw(){\n    const r = M.L/52;\n    // spelare\n    cur.forEach((p,i)=>{\n      const e = playerEls[i];\n      e.g.setAttribute(\"transform\",`translate(${p.x.toFixed(2)},${p.y.toFixed(2)})${kitRot()}`);\n      let ringCol = \"transparent\", fill = \"transparent\";\n      if(i===roles.press){ ringCol = \"var(--press)\"; fill = \"rgba(229,72,77,.35)\"; }\n      else if(i===roles.cover){ ringCol = \"var(--cover)\"; fill = \"rgba(245,184,46,.3)\"; }\n      e.ring.setAttribute(\"stroke\",ringCol);\n      e.pin.setAttribute(\"stroke\", ourPinned[i] ? \"rgba(255,255,255,.85)\" : \"transparent\");\n      e.c.setAttribute(\"fill\",fill);\n    });\n    // bollen\n    gBall.setAttribute(\"transform\",`translate(${ballDisp.x.toFixed(2)},${ballDisp.y.toFixed(2)})`);\n\n    // motståndare\n    // I anfallsläge är \"motståndarna\" det försvarande laget (M.players), och vårt lag är M.opp\n    const defVis = !attack || opts.opp;\n    gOpp.style.display = (attack || opts.opp) ? \"\" : \"none\";\n    [gPlayers, gOverlay, gMark].forEach(g=> g.style.display = defVis ? \"\" : \"none\");\n    if(!defVis) gGhost.style.display = \"none\";\n    oppCur.forEach((p,i)=>{\n      oppEls[i].g.setAttribute(\"transform\",`translate(${p.x.toFixed(2)},${p.y.toFixed(2)})${kitRot()}`);\n      oppEls[i].pin.setAttribute(\"stroke\", oppPinned[i] ? \"rgba(255,255,255,.8)\" : \"transparent\");\n      oppEls[i].lab.style.display = opts.attPos ? \"\" : \"none\";\n    });\n    // markeringslinjer\n    markEls.forEach(m=>m.style.display=\"none\");\n    if(oppLogic() && opts.cover){\n      marking.forEach(([i,j],k)=>{\n        if(i===roles.press || i===roles.cover || !markEls[k]) return;\n        const a = cur[i], b = oppCur[j];\n        markEls[k].style.display = \"\";\n        markEls[k].setAttribute(\"x1\",a.x); markEls[k].setAttribute(\"y1\",a.y);\n        markEls[k].setAttribute(\"x2\",b.x); markEls[k].setAttribute(\"y2\",b.y);\n      });\n    }\n\n    // spöken (grundposition utan press/täck)\n    gGhost.style.display = (opts.base && (!attack || opts.opp)) ? \"\" : \"none\";\n    if(opts.base && lastBase){\n      lastBase.pts.forEach((p,i)=>{ ghostEls[i].setAttribute(\"cx\",p.x); ghostEls[i].setAttribute(\"cy\",p.y); });\n    }\n\n    // lagdelslinjer (aktuella positioner, sorterat i bredd)\n    const units = [1,2,3].map(u=> M.players.map((p,i)=>({p,i})).filter(o=>o.p.unit===u && o.i!==roles.press && o.i!==roles.cover).map(o=>cur[o.i]).sort((a,b)=>a.y-b.y));\n    [\"l1\",\"l2\",\"l3\"].forEach((k,idx)=>{\n      const pts = units[idx];\n      overlayEls[k].style.display = (opts.lines && pts.length>1) ? \"\" : \"none\";\n      overlayEls[k].setAttribute(\"points\", pts.map(p=>`${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(\" \"));\n    });\n\n    // kompakthet: utespelare\n    const outfield = cur.slice(1);\n    const h = hull(outfield);\n    overlayEls.box.style.display = opts.box ? \"\" : \"none\";\n    overlayEls.box.setAttribute(\"points\", h.map(p=>`${p.x.toFixed(2)},${p.y.toFixed(2)}`).join(\" \"));\n\n    // pilar\n    const showArr = opts.cover && roles.press>=0;\n    overlayEls.pressArr.style.display = showArr ? \"\" : \"none\";\n    overlayEls.coverArr.style.display = showArr && roles.cover>=0 ? \"\" : \"none\";\n    if(showArr){\n      const p = cur[roles.press];\n      const d = dist(p,ball);\n      if(d > r*1.4){\n        const ux=(ball.x-p.x)/d, uy=(ball.y-p.y)/d;\n        overlayEls.pressArr.setAttribute(\"x1\",p.x+ux*r*1.2); overlayEls.pressArr.setAttribute(\"y1\",p.y+uy*r*1.2);\n        overlayEls.pressArr.setAttribute(\"x2\",ball.x-ux*r*0.9); overlayEls.pressArr.setAttribute(\"y2\",ball.y-uy*r*0.9);\n      } else {\n        overlayEls.pressArr.style.display = \"none\";\n      }\n      if(roles.cover>=0){\n        const c = cur[roles.cover];\n        overlayEls.coverArr.setAttribute(\"x1\",c.x); overlayEls.coverArr.setAttribute(\"y1\",c.y);\n        overlayEls.coverArr.setAttribute(\"x2\",p.x); overlayEls.coverArr.setAttribute(\"y2\",p.y);\n      }\n    }\n\n    // statistik\n    const xs = outfield.map(p=>p.x), ys = outfield.map(p=>p.y);\n    // lagets längd mäts mellan djupaste och högsta utespelare (exkl. pressande spelare som kan sticka ut)\n    const blk = outfield.filter((p,i)=> (i+1)!==roles.press);\n    const bx = blk.map(p=>p.x), byy = blk.map(p=>p.y);\n    document.getElementById(\"sLen\").textContent = Math.round(Math.max(...bx)-Math.min(...bx));\n    document.getElementById(\"sWid\").textContent = Math.round(Math.max(...byy)-Math.min(...byy));\n    document.getElementById(\"sLine\").textContent = lastBase ? Math.round(lastBase.lineX) : \"–\";\n    document.getElementById(\"sBall\").textContent = Math.round(ball.x);\n  }\n\n  // ---------- Förklaringstext ----------\n  function explain(){\n    const {L,W} = M;\n    document.getElementById(\"kLen\").textContent = attack ? \"Motståndarnas längd (m)\" : \"Lagets längd (m)\";\n    document.getElementById(\"kWid\").textContent = attack ? \"Motståndarnas bredd (m)\" : \"Lagets bredd (m)\";\n    document.getElementById(\"kBall\").textContent = attack ? \"Bollen från deras mål (m)\" : \"Bollen från vårt mål (m)\";\n    if(attack){ explainAttack(); return; }\n    const p = M.players[roles.press], c = roles.cover>=0 ? M.players[roles.cover] : null;\n    const third = ball.x < L/3 ? \"def\" : ball.x < 2*L/3 ? \"mid\" : \"off\";\n    const side = ball.y < W*0.3 ? \"vänster\" : ball.y > W*0.7 ? \"höger\" : \"central\";\n    const inBox = ball.x <= M.boxD && Math.abs(ball.y - W/2) <= M.boxW/2;\n    let html = p ? `<p><b style=\"color:var(--press)\">Nr ${p.n} (${p.pos})</b> pressar bollhållaren och stänger vägen mot mål.</p>` : `<p>Alla utespelare är låsta, så ingen pressar automatiskt.</p>`;\n    const nPinned = ourPinned.filter(Boolean).length;\n    if(nPinned) html += `<p>${nPinned} av våra spelare är handflyttade (streckad ring) och står kvar där du ställt dem. Övriga anpassar sig.</p>`;\n    if(c) html += `<p><b style=\"color:var(--cover)\">Nr ${c.n} (${c.pos})</b> täcker snett bakom – om pressen blir överspelad är hen nästa försvarare.</p>`;\n    if(inBox){\n      html += `<p>Bollen är i vårt straffområde. Alla hjälps åt nära mål, markera spelare och ytor framför mål. Målvakten styr.</p>`;\n    } else if(third===\"def\"){\n      html += `<p>Bollen är i vår tredjedel. Backlinjen ligger djupt, mittfältet faller ner framför backarna så att det inte finns ytor mellan lagdelarna.</p>`;\n    } else if(third===\"mid\"){\n      html += `<p>Bollen är på mitten. Laget är kompakt och ligger på rätt sida om bollen, backlinjen ca ${Math.round(lastBase.lineX)} m från eget mål.</p>`;\n    } else {\n      html += `<p>Bollen är högt upp. Laget kliver upp tillsammans så att avståndet mellan lagdelarna inte blir för stort, men backlinjen släpper inte bakom sig.</p>`;\n    }\n    if(side!==\"central\"){\n      html += `<p>Bollen är på <b>${side}kanten</b>: hela laget förskjuts mot bollsidan och spelarna på bortre sidan går in mot mitten.</p>`;\n    } else {\n      html += `<p>Bollen är <b>centralt</b>: laget smalnar av och stänger mitten först.</p>`;\n    }\n    if(opts.opp && lastBase){\n      html += `<p>Vi spelar <b>${ourSel[modeKey]}</b>, motståndarna <b>${oppSel[modeKey]}</b>. Vårt lag förhåller sig mest till <b>${[\"bollen (zon)\",\"både boll och motståndare\",\"motståndarna\"][relate]}</b>.</p>`;\n      // motståndare mellan backlinje och mittfält, innanför lagets bredd\n      const ys = tgt.slice(1).map(p=>p.y);\n      const y0 = Math.min(...ys), y1 = Math.max(...ys);\n      const between = oppTgt.filter((q,j)=> !M.opp[j].gk && q.x > lastBase.lineX + 1 && q.x < lastBase.midX - 1 && q.y > y0 && q.y < y1).length;\n      const marked = marking.filter(([i])=> i!==roles.press && i!==roles.cover).length;\n      if(marked) html += `<p>${marked} av våra spelare har en motståndare i sin zon (streckade linjer) och ställer sig på målsidan om den.</p>`;\n      if(between) html += `<p><b>Varning:</b> ${between} motståndare står mellan vår backlinje och vårt mittfält. Minska avståndet mellan lagdelarna eller låt en mittfältare falla ner.</p>`;\n    }\n    document.getElementById(\"explain\").innerHTML = html;\n  }\n\n  function explainAttack(){\n    const {L,W} = M;\n    const p = roles.press>=0 ? M.players[roles.press] : null, c = roles.cover>=0 ? M.players[roles.cover] : null;\n    let html = `<p>Vi spelar <b>${ourSel[modeKey]}</b> mot motståndarnas <b>${oppSel[modeKey]}</b>.</p>`;\n    if(p) html += `<p>Deras <b style=\"color:var(--press)\">nr ${p.n}</b> pressar vår bollhållare${c ? `, och <b style=\"color:var(--cover)\">nr ${c.n}</b> täcker bakom` : \"\"}.</p>`;\n    if(lastBase){\n      // våra spelare mellan deras backlinje och mittfält\n      const ys = tgt.slice(1).map(q=>q.y);\n      const y0 = Math.min(...ys)-2, y1 = Math.max(...ys)+2;\n      let carrier = -1, bd=1e9; oppTgt.forEach((q,j)=>{ const d=dist(q,ball); if(d<bd){bd=d;carrier=j;} });\n      const between = oppTgt.map((q,j)=>({q,j})).filter(o=> !M.opp[o.j].gk && o.j!==carrier && o.q.x > lastBase.lineX + 1 && o.q.x < lastBase.midX - 1 && o.q.y > y0 && o.q.y < y1);\n      if(between.length) html += `<p><b>Bra läge:</b> ${between.map(o=>\"nr \"+M.opp[o.j].n).join(\", \")} står mellan deras backlinje och mittfält. Där finns yta att spela in i.</p>`;\n      // omarkerade spelare (ingen försvarare har dem i sin zon)\n      const markedSet = new Set(marking.filter(([i])=> i!==roles.press && i!==roles.cover).map(([,j])=>j));\n      // spelbara: omarkerade och inte långt bakom bollen\n      const free = oppTgt.map((q,j)=>j).filter(j=> j!==carrier && !M.opp[j].gk && !markedSet.has(j) && oppTgt[j].x < ball.x + M.L*0.15);\n      if(free.length) html += `<p><b>Spelbara:</b> ${free.map(j=>\"nr \"+M.opp[j].n).join(\", \")} har ingen försvarare i sin zon. Tryck på en spelare för att passa.</p>`;\n      const len = Math.round(Math.max(...tgt.slice(1).map(q=>q.x)) - Math.min(...tgt.slice(1).map(q=>q.x)));\n      html += `<p>Motståndarnas backlinje står ca ${Math.round(lastBase.lineX)} m från eget mål och laget är ${len} m långt. ${lastBase.lineX > L*0.3 ? \"Det finns yta bakom backlinjen för djupledslöpningar.\" : \"De försvarar djupt – sök ytan framför backlinjen och spelvändningar.\"}</p>`;\n    }\n    const side = ball.y < W*0.3 ? \"höger\" : ball.y > W*0.7 ? \"vänster\" : null;\n    if(side) html += `<p>Bollen är på vår <b>${side}kant</b>. Försvaret förskjuts dit, så bortre kanten blir ofta fri för en spelvändning.</p>`;\n    document.getElementById(\"explain\").innerHTML = html;\n  }\n\n  // ---------- Animation ----------\n  function tick(){\n    let moving = false;\n    for(let i=0;i<cur.length;i++){\n      if(ourPinned[i] && dragOur===i){ cur[i] = {...ourPinned[i]}; continue; }\n      const dx = tgt[i].x - cur[i].x, dy = tgt[i].y - cur[i].y;\n      if(Math.abs(dx)>0.02 || Math.abs(dy)>0.02){ moving = true; }\n      cur[i].x += dx*0.14; cur[i].y += dy*0.14;\n    }\n    for(let i=0;i<oppCur.length && i<oppTgt.length;i++){\n      if(oppPinned[i] && dragOpp===i){ oppCur[i] = {...oppPinned[i]}; continue; }\n      oppCur[i].x += (oppTgt[i].x-oppCur[i].x)*0.14; oppCur[i].y += (oppTgt[i].y-oppCur[i].y)*0.14;\n    }\n    if(dragging){ ballDisp = {...ball}; }\n    else { ballDisp.x += (ball.x-ballDisp.x)*0.22; ballDisp.y += (ball.y-ballDisp.y)*0.22; }\n    draw();\n    requestAnimationFrame(tick);\n  }\n\n  function setBall(x,y){\n    ball.x = clamp(x, 0.5, M.L-0.5);\n    ball.y = clamp(y, 0.5, M.W-0.5);\n    const t = computeTargets();\n    tgt = t.pts;\n    updateOverlay(t);\n    explain();\n  }\n\n  // ---------- Interaktion ----------\n  function svgPoint(evt){\n    const pt = svg.createSVGPoint();\n    pt.x = evt.clientX; pt.y = evt.clientY;\n    const m = (gRoot || svg).getScreenCTM();\n    if(!m) return {x:ball.x,y:ball.y};\n    const p = pt.matrixTransform(m.inverse());\n    return {x:p.x, y:p.y};\n  }\n  let dragging = false, oppStart = null, oppMoved = false;\n  svg.addEventListener(\"pointerdown\", e=>{\n    try{ svg.setPointerCapture(e.pointerId); }catch(_){}\n    const p = svgPoint(e);\n    e.preventDefault();\n    const r = M.L/52;\n    // träff på en spelare i det försvarande laget (om det syns)?\n    if((!attack || opts.opp) && dist(p, ballDisp) > r*0.9){\n      let hit=-1, hd=r*1.3;\n      cur.forEach((q,i)=>{ const d=dist(q,p); if(d<hd){hd=d;hit=i;} });\n      if(hit>=0){ dragOur = hit; oppStart = p; oppMoved = false; return; }\n    }\n    // träff på motståndare? (bollen har företräde om man tar precis på den)\n    if(oppLogic() && dist(p, ballDisp) > r*0.9){\n      let hit=-1, hd=r*1.5;\n      oppCur.forEach((q,i)=>{ const d=dist(q,p); if(d<hd){hd=d;hit=i;} });\n      if(hit>=0){ dragOpp = hit; oppStart = p; oppMoved = false; return; }\n    }\n    dragging = true;\n    setBall(p.x,p.y);\n  });\n  svg.addEventListener(\"pointermove\", e=>{\n    const p = svgPoint(e);\n    if(dragOur>=0){\n      if(!oppMoved && dist(p,oppStart) < M.L/150) return;\n      oppMoved = true;\n      ourPinned[dragOur] = {x: clamp(p.x,0.5,M.L-0.5), y: clamp(p.y,0.5,M.W-0.5)};\n      setBall(ball.x, ball.y);\n      return;\n    }\n    if(dragOpp>=0){\n      if(!oppMoved && dist(p,oppStart) < M.L/150) return;\n      oppMoved = true;\n      const was = oppPinned[dragOpp] || oppCur[dragOpp];\n      // flyttar man bollhållaren följer bollen med\n      const hadBall = dist(was, ball) < 3;\n      oppPinned[dragOpp] = {x: clamp(p.x,0.5,M.L-0.5), y: clamp(p.y,0.5,M.W-0.5)};\n      if(hadBall) setBall(oppPinned[dragOpp].x - M.L/90, oppPinned[dragOpp].y);\n      else setBall(ball.x, ball.y);\n      return;\n    }\n    if(!dragging) return;\n    setBall(p.x,p.y);\n  });\n  const end = e=>{\n    if(dragOur>=0 && !oppMoved){\n      // tryck på en låst spelare = släpp den tillbaka till laget\n      if(ourPinned[dragOur]){ ourPinned[dragOur] = null; setBall(ball.x, ball.y); }\n    }\n    dragOur = -1;\n    if(dragOpp>=0 && !oppMoved){\n      // tryck = passa bollen till motståndaren\n      const q = oppCur[dragOpp];\n      oppPinned[dragOpp] = {x:q.x, y:q.y};\n      setBall(q.x - M.L/90, q.y);\n    }\n    dragOpp = -1; dragging = false;\n  };\n  svg.addEventListener(\"pointerup\", end);\n  svg.addEventListener(\"pointercancel\", end);\n\n  // presets\n  const pres = document.getElementById(\"presets\");\n  function renderPresets(){\n    pres.innerHTML = \"\";\n    PRESETS.forEach(pr=>{\n      const b = document.createElement(\"button\");\n      b.textContent = attack ? pr.a : pr.label;\n      b.addEventListener(\"click\", ()=>{ oppPinned = []; ourPinned = []; setBall(pr.x*M.L, pr.y*M.W); });\n      pres.appendChild(b);\n    });\n  }\n  renderPresets();\n  // Vilket lag som försvarar (M.players) och anfaller (M.opp) beror på läget\n  function applyForms(){\n    if(!attack){ M.players = OURF[modeKey][ourSel[modeKey]]; M.opp = OPPF[modeKey][oppSel[modeKey]]; }\n    else { M.players = OURF[modeKey][oppSel[modeKey]]; M.opp = OPPF[modeKey][ourSel[modeKey]]; }\n  }\n\n  // läge\n  document.querySelectorAll(\"#modeSeg button\").forEach(b=>{\n    b.addEventListener(\"click\", ()=>{\n      document.querySelectorAll(\"#modeSeg button\").forEach(x=>x.classList.remove(\"on\"));\n      b.classList.add(\"on\");\n      const fx = ball.x / M.L, fy = ball.y / M.W;\n      modeKey = b.dataset.mode; M = MODES[modeKey]; applyForms();\n      ball = {x: fx*M.L, y: fy*M.W};\n      oppPinned = []; ourPinned = [];\n      syncGap();\n      renderOppForms(); renderOurForms();\n      build(); explain();\n    });\n  });\n\n  // val\n  const bind = (id,key)=> document.getElementById(id).addEventListener(\"change\", e=>{ opts[key] = e.target.checked; });\n  bind(\"cLines\",\"lines\"); bind(\"cBox\",\"box\"); bind(\"cCover\",\"cover\"); bind(\"cBase\",\"base\");\n  document.getElementById(\"cCorr\").addEventListener(\"change\", e=>{ opts.corr = e.target.checked; if(gCorr) gCorr.style.display = opts.corr ? \"\" : \"none\"; });\n  document.getElementById(\"cAttPos\").addEventListener(\"change\", e=>{ opts.attPos = e.target.checked; });\n  document.getElementById(\"cOpp\").addEventListener(\"change\", e=>{ opts.opp = e.target.checked; setBall(ball.x,ball.y); });\n  function renderOurForms(){\n    const box = document.getElementById(\"ourForms\");\n    box.innerHTML = \"\";\n    Object.keys(OURF[modeKey]).forEach(f=>{\n      const b = document.createElement(\"button\");\n      b.textContent = f;\n      if(f===ourSel[modeKey]) b.classList.add(\"on\");\n      b.addEventListener(\"click\", ()=>{\n        ourSel[modeKey] = f; applyForms(); ourPinned = []; oppPinned = [];\n        renderOurForms(); build(); explain();\n      });\n      box.appendChild(b);\n    });\n  }\n  function renderOppForms(){\n    const box = document.getElementById(\"oppForms\");\n    box.innerHTML = \"\";\n    Object.keys(OPPF[modeKey]).forEach(f=>{\n      const b = document.createElement(\"button\");\n      b.textContent = f;\n      if(f===oppSel[modeKey]) b.classList.add(\"on\");\n      b.addEventListener(\"click\", ()=>{\n        oppSel[modeKey] = f; applyForms(); oppPinned = []; ourPinned = [];\n        if(!opts.opp){ opts.opp = true; document.getElementById(\"cOpp\").checked = true; }\n        renderOppForms(); build(); explain();\n      });\n      box.appendChild(b);\n    });\n  }\n  document.getElementById(\"rRel\").addEventListener(\"input\", e=>{\n    relate = +e.target.value;\n    document.getElementById(\"vRel\").textContent = [\"bollen\",\"båda\",\"motståndarna\"][relate];\n    setBall(ball.x,ball.y);\n  });\n  // ourPinned gäller alltid det försvarande laget och oppPinned det anfallande.\n  // När vi anfaller är vårt lag det anfallande, så knapparna byter vilken lista de nollställer.\n  document.getElementById(\"bResetOur\").addEventListener(\"click\", ()=>{ if(attack) oppPinned = []; else ourPinned = []; setBall(ball.x,ball.y); });\n  document.getElementById(\"bResetOpp\").addEventListener(\"click\", ()=>{ if(attack) ourPinned = []; else oppPinned = []; setBall(ball.x,ball.y); });\n\n  const words = [\"låg\",\"normal\",\"hög\"];\n  const words2 = [\"liten\",\"normal\",\"stor\"];\n  document.getElementById(\"rHigh\").addEventListener(\"input\", e=>{ high = +e.target.value; document.getElementById(\"vHigh\").textContent = words[high]; setBall(ball.x,ball.y); });\n  document.getElementById(\"rShift\").addEventListener(\"input\", e=>{ shiftLevel = +e.target.value; document.getElementById(\"vShift\").textContent = words2[shiftLevel]; setBall(ball.x,ball.y); });\n\n  const rGap = document.getElementById(\"rGap\");\n  function syncGap(){\n    rGap.min = M.gapRange[0]; rGap.max = M.gapRange[1]; rGap.value = M.gapCur;\n    document.getElementById(\"vGap\").textContent = M.gapCur + \" m\";\n  }\n  rGap.addEventListener(\"input\", e=>{\n    M.gapCur = +e.target.value;\n    document.getElementById(\"vGap\").textContent = M.gapCur + \" m\";\n    setBall(ball.x,ball.y);\n  });\n\n  syncGap();\n  renderOppForms();\n  renderOurForms();\n  const bRot = document.getElementById(\"bRotate\");\n  function syncRot(){\n    bRot.textContent = portrait ? \"⟲ Liggande plan\" : \"⟲ Stående plan\";\n    document.querySelectorAll(\"#attSeg button\").forEach(b=>b.classList.toggle(\"on\", (b.dataset.att===\"1\")===attack));\n    document.querySelector(\"h1\").textContent = attack ? \"Anfallsspel – mot zonförsvar\" : \"Försvarsspel – zonförsvar\";\n    document.getElementById(\"subTxt\").textContent = attack\n      ? \"Vi anfaller mot målet \" + (portrait ? \"överst\" : \"till höger\") + \". Tryck på en av våra spelare för att passa, eller dra spelare till nya ytor. Motståndarna försvarar med zonförsvar.\"\n      : \"Dra bollen (eller klicka på planen). Hela laget förflyttar sig efter bollen. Vi försvarar målet \" + (portrait ? \"nederst.\" : \"till vänster.\");\n    document.getElementById(\"hintTxt\").textContent = attack\n      ? \"Tryck på en av våra spelare (gul) för att passa bollen dit – motståndarnas försvar flyttar sig direkt. Dra spelare till nya ytor för att se hur försvaret svarar. Tryck på en låst blå spelare för att släppa tillbaka den.\"\n      : \"Dra en spelare – vår eller motståndarnas – för att flytta den. Den stannar där du släpper den (streckad ring). Tryck på en låst spelare i vårt lag för att släppa tillbaka den till laget. Tryck på en motståndare för att passa bollen till den. Tips: visa sidan på projektor eller mobil och låt spelarna förklara vem som ska pressa, täcka och flytta in.\";\n    document.getElementById(\"setHead\").textContent = attack ? \"Inställningar (motståndarnas försvar)\" : \"Inställningar\";\n  }\n  document.querySelectorAll(\"#attSeg button\").forEach(b=>b.addEventListener(\"click\", ()=>{\n    if((b.dataset.att===\"1\")===attack) return;\n    attack = !attack;\n    // spegla bollen så att den ligger kvar på samma ställe på skärmen\n    ball = {x: M.L - ball.x, y: M.W - ball.y};\n    oppPinned = []; ourPinned = [];\n    applyForms(); renderPresets(); syncRot(); build(); explain();\n  }));\n  bRot.addEventListener(\"click\", ()=>{ portrait = !portrait; syncRot(); build(); explain(); });\n  syncRot();\n  build();\n  explain();\n  requestAnimationFrame(tick);\n})();\n</script>\n</body>\n</html>"
